import json
from .common import ROOT

def build_offline(pred,scores,bench,selected):
    rows=pred.reset_index().copy()
    rows["timestamp"]=rows["timestamp"].dt.strftime("%Y-%m-%d %H:%M")
    labs=[]
    for size in [8760,100000,1000000]:
        folder=ROOT/f"results/lab/{size}"
        if (folder/"summary.json").exists():
            labs.append({"summary":json.loads((folder/"summary.json").read_text(encoding="utf-8")),
                         "plan":(folder/"plan_partition_filter.txt").read_text(encoding="utf-8")})
    data=json.dumps({"rows":rows.round(3).to_dict("records"),"scores":scores.round(3).to_dict("records"),
                     "bench":bench.round(3).to_dict("records"),"selected":selected,"labs":labs},ensure_ascii=False,allow_nan=False)
    template='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Seoul Bike — Kết quả thực nghiệm</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7f7;color:#193449;font:16px system-ui,sans-serif}header{background:#193449;color:white;padding:44px max(5%,calc((100vw - 1160px)/2))}h1{font-size:clamp(26px,4vw,42px);margin:8px 0}header p{color:#c6dfe0;max-width:850px;line-height:1.6}main{max-width:1160px;margin:auto;padding:24px}section{background:white;padding:28px;margin:18px 0;border:1px solid #dde6e7;border-radius:8px}h2{font-size:24px;margin-top:0}.notice{border-left:4px solid #dd6e42;padding:12px 18px;background:#fff6ef;line-height:1.6}label{display:inline-block;margin:10px 24px 14px 0}input,select{font:inherit;padding:9px;border:1px solid #95a9ad;border-radius:4px;display:block;margin-top:6px}canvas{width:100%;height:340px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px 10px;border-bottom:1px solid #dde6e7;text-align:right}th:first-child,td:first-child{text-align:left}th{background:#eef4f4}.scroll{overflow:auto}.metrics{display:flex;flex-wrap:wrap;gap:35px;margin:24px 0}.metrics strong{display:block;font-size:32px;color:#007f85}.muted{color:#526a73;font-size:14px;line-height:1.6}.legend{display:flex;gap:24px;flex-wrap:wrap}.legend span:before{content:'';display:inline-block;width:22px;height:3px;margin:0 7px 4px 0;background:var(--c)}a{color:#007f85}footer{text-align:center;padding:28px;color:#526a73}li{margin:10px 0;line-height:1.5}</style>
<header><div>PHÂN TÍCH DỮ LIỆU LỚN · ĐỀ TÀI 4</div><h1>Dự báo nhu cầu xe đạp Seoul</h1><p>8.760 giờ quan sát · 21 đặc trưng lịch sử và lịch · Spark ML Pipeline · Kiểm chứng theo thời gian</p></header>
<main><p class="notice"><b>Bản xem kết quả offline.</b> Trang này hiển thị dự báo đã tính trong thực nghiệm, không chạy mô hình mới. Để dự báo trực tiếp từ lịch sử hoặc CSV, chạy dashboard Streamlit theo README.</p>
<section><h2>Thành quả xử lý Spark</h2><p>CSV gốc → kiểm tra chất lượng → Parquet theo tháng → tổng hợp SQL. Chọn quy mô để xem kết quả đã chạy và kế hoạch lọc tháng. Bản này không chạy Spark trong trình duyệt.</p><label>Quy mô đã xử lý<select id="lab-size"></select></label><div class="scroll" id="lab-results"></div><details><summary>Kế hoạch đọc Parquet và lọc phân vùng</summary><pre id="lab-plan" style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.5"></pre></details><p class="muted">PartitionFilters cho thấy bộ lọc tháng trong kế hoạch. Dữ liệu 100 nghìn/1 triệu hàng là bản lặp chỉ để thử tải; mô hình dùng dữ liệu thật.</p></section>
<section><h2>Kết quả của mô hình chọn bằng validation</h2><p id="selection"></p><div class="metrics" id="metrics"></div><p class="muted">Kiểm tra 01/10–30/11/2018, 1.464 giờ. Cập nhật quan sát sau từng giờ, không huấn luyện lại trong tập kiểm tra. MAPE chỉ tính trên 1.313 giờ có nhãn lớn hơn 0.</p></section>
<section><h2>Phát lại kết quả theo thời gian</h2><label>Ngày bắt đầu<input id="date" type="date" min="2018-10-01" max="2018-11-30" value="2018-10-01"></label><label>Số ngày<select id="days"><option>1</option><option selected>7</option><option>14</option></select></label><label>Mô hình<select id="model"></select></label><p class="legend"><span style="--c:#193449">Thực tế</span><span style="--c:#007f85">Mô hình</span><span style="--c:#dd6e42">Giờ trước</span></p><canvas id="chart" aria-label="Biểu đồ số lượt thuê thực tế và dự báo" role="img"></canvas><p class="muted" id="range"></p></section>
<section><h2>So sánh mô hình trên tập kiểm tra</h2><div class="scroll" id="scores"></div><p class="muted">MAE/RMSE tính trên tất cả 1.464 giờ, kể cả 151 giờ có nhãn bằng 0. Mô hình triển khai được chọn bằng MAE validation, không đổi lựa chọn theo kết quả test.</p></section>
<section><h2>Spark và pandas trên cùng tác vụ ETL</h2><div class="scroll" id="bench"></div><p class="muted">Trung vị 3 lượt đo. local[2], một máy, cùng CSV và phép tổng hợp. ETL không gồm khởi động Spark, thời gian toàn trình có gồm. RSS lấy mẫu cả Python và JVM, có thể đếm trùng trang nhớ dùng chung. Hệ điều hành có thể giữ cache. Quy mô lớn được nhân bản chỉ để thử tải.</p></section>
<section><h2>Phạm vi và cách trình bày</h2><ul><li>Dự báo trước 1 giờ bằng dữ liệu đã quan sát đến giờ trước. Không dùng thời tiết tương lai hoặc số lượt thuê của giờ cần dự báo.</li><li>Dữ liệu gốc có 295 giờ đóng dịch vụ. Các giờ này vẫn thuộc đánh giá.</li><li>Đây là backtest lịch sử. Pilot ban đầu đã xem giai đoạn chồng lấn nên không xem đây là kiểm định độc lập chưa từng được quan sát.</li><li>Đo Spark tại một máy không chứng minh ưu thế của cụm phân tán hoặc hiệu năng ở quy mô lớn hơn đã đo.</li></ul><p><a href="README.md">Hướng dẫn chạy</a> · <a href="results/predictions.csv" download>Dự báo CSV</a> · <a href="docs/Bao_cao_Seoul_Bike.pdf">Báo cáo PDF</a></p></section>
</main><footer>Nguồn UCI Seoul Bike Sharing Demand · DOI 10.24432/C5F62R · CC BY 4.0</footer><script>
const DATA=__DATA__;
const names=['Ridge','RandomForest','HistGradientBoosting','SparkRandomForest'];
const f=(x,d=2)=>Number(x).toLocaleString('vi-VN',{maximumFractionDigits:d,minimumFractionDigits:d});
const chosen=DATA.scores.find(r=>r.model===DATA.selected);document.getElementById('selection').textContent=DATA.selected+' — MAE trung bình thấp nhất trên 3 tháng validation.';
document.getElementById('metrics').innerHTML=[['MAE',chosen.MAE],['RMSE',chosen.RMSE],['MAPE dương (%)',chosen.MAPE_positive_pct]].map(([n,v])=>`<div><strong>${f(v)}</strong>${n}</div>`).join('');
document.getElementById('model').innerHTML=names.map(n=>`<option ${n===DATA.selected?'selected':''}>${n}</option>`).join('');
function table(id,heads,rows){document.getElementById(id).innerHTML='<table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
document.getElementById('lab-size').innerHTML=DATA.labs.map((r,i)=>`<option value="${i}">${r.summary.processed_rows.toLocaleString('vi-VN')} hàng${r.summary.replicated?' (nhân bản thử tải)':' (dữ liệu thật)'}</option>`).join('');
function showLab(){const item=DATA.labs[Number(document.getElementById('lab-size').value)];if(!item){document.getElementById('lab-results').textContent='Chưa có kết quả lab. Chạy python run_project.py --lab.';return}const s=item.summary;table('lab-results',['Minh chứng','Kết quả'],[['Giờ nguồn thật',s.source_rows.toLocaleString('vi-VN')],['Hàng xử lý',s.processed_rows.toLocaleString('vi-VN')],['Phân vùng tháng',s.month_partitions],['Nhóm tháng × giờ',s.aggregate_groups],['Hàng lọc tháng '+s.query_month,s.query_rows.toLocaleString('vi-VN')],['SQL khớp tham chiếu pandas',s.aggregates_match_pandas?'Đạt':'Chưa đạt']]);document.getElementById('lab-plan').textContent=item.plan}
document.getElementById('lab-size').addEventListener('change',showLab);showLab();
table('scores',['Mô hình','MAE','RMSE','MAPE dương (%)','WAPE (%)'],DATA.scores.map(r=>[r.model+(r.model===DATA.selected?' ★':''),f(r.MAE),f(r.RMSE),f(r.MAPE_positive_pct),f(r.WAPE_pct)]));
table('bench',['Số dòng','Công cụ','ETL (giây)','Toàn trình (giây)','RSS đỉnh (MiB)'],DATA.bench.map(r=>[r.size.toLocaleString('vi-VN'),r.engine,f(r.etl_median_s,3),f(r.wall_median_s,3),f(r.peak_rss_median_mib,1)]));
function draw(){let start=document.getElementById('date').value;if(!start)return;let rows=DATA.rows.filter(r=>r.timestamp.slice(0,10)>=start).slice(0,24*Number(document.getElementById('days').value));if(!rows.length)return;const name=document.getElementById('model').value;const c=document.getElementById('chart'),ratio=window.devicePixelRatio||1,W=c.clientWidth,H=340;c.width=W*ratio;c.height=H*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);ctx.clearRect(0,0,W,H);const left=58,right=16,top=20,bottom=42;const max=Math.max(1,...rows.flatMap(r=>[r.count,r[name],r.Naive_1h]))*1.1;ctx.font='12px system-ui';ctx.fillStyle='#526a73';for(let k=0;k<5;k++){const y=top+(H-top-bottom)*k/4;ctx.strokeStyle='#e2eaeb';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(W-right,y);ctx.stroke();ctx.fillText(Math.round(max*(1-k/4)),3,y+4)}for(const [key,color]of[['Naive_1h','#dd6e42'],['count','#193449'],[name,'#007f85']]){ctx.strokeStyle=color;ctx.lineWidth=key==='Naive_1h'?1:2;ctx.beginPath();rows.forEach((r,i)=>{let x=left+i*(W-left-right)/Math.max(1,rows.length-1),y=top+(1-r[key]/max)*(H-top-bottom);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}ctx.fillText(rows[0].timestamp,left,H-12);ctx.textAlign='right';ctx.fillText(rows.at(-1).timestamp,W-right,H-12);ctx.textAlign='left';document.getElementById('range').textContent=rows.length+' giờ · Trục dọc: lượt thuê/giờ · Trục ngang: giờ địa phương Seoul.'}
['date','days','model'].forEach(id=>document.getElementById(id).addEventListener('change',draw));window.addEventListener('resize',draw);draw();
</script></html>'''
    (ROOT/"DEMO_OFFLINE.html").write_text(template.replace("__DATA__",data),encoding="utf-8")
